const reports = $('Get Last 30 Days Reports').all();
const feedbacks = $('Get Last 30 Days Feedback').all();

if (reports.length === 0) {
  return [{ json: { no_data: true } }];
}

// Calculate metrics
const totalReports = reports.length;
const confidenceScores = reports.map(r => parseFloat(r.json.fields.confidence_score || 0));
const avgConfidence = confidenceScores.reduce((a, b) => a + b, 0) / totalReports;
const highConfidence = confidenceScores.filter(s => s >= 75).length;
const lowConfidence = confidenceScores.filter(s => s < 60).length;

// Group by company
const byCompany = {};
reports.forEach(r => {
  const company = r.json.fields.company_name || 'Unknown';
  if (!byCompany[company]) {
    byCompany[company] = { count: 0, avgConfidence: 0, scores: [] };
  }
  byCompany[company].count++;
  byCompany[company].scores.push(parseFloat(r.json.fields.confidence_score || 0));
});

Object.keys(byCompany).forEach(company => {
  const scores = byCompany[company].scores;
  byCompany[company].avgConfidence = (scores.reduce((a, b) => a + b, 0) / scores.length).toFixed(2);
});

// Top companies
const topCompanies = Object.entries(byCompany)
  .sort((a, b) => b[1].count - a[1].count)
  .slice(0, 5)
  .map(([name, data]) => ({ name, count: data.count, avgConfidence: data.avgConfidence }));

// Feedback metrics
const totalFeedback = feedbacks.length;
const avgRating = feedbacks.length > 0 
  ? (feedbacks.reduce((sum, f) => sum + parseInt(f.json.fields.rating || 0), 0) / totalFeedback).toFixed(2)
  : 'N/A';
const recommendRate = feedbacks.length > 0
  ? ((feedbacks.filter(f => f.json.fields.would_recommend === true).length / totalFeedback) * 100).toFixed(1)
  : 'N/A';

// Market signals trends
const signalTrends = {
  ai_chip: (reports.reduce((sum, r) => sum + (r.json.fields.ai_chip_rate || 0), 0) / totalReports).toFixed(1),
  supply_risk: (reports.reduce((sum, r) => sum + (r.json.fields.supply_risk || 0), 0) / totalReports).toFixed(1)
};

// Get unique users
const uniqueUsers = new Set(reports.map(r => r.json.fields.user_email)).size;

// Month metadata
const now = new Date();
const lastMonth = new Date(now.getFullYear(), now.getMonth() - 1, 1);
const monthName = lastMonth.toLocaleString('default', { month: 'long', year: 'numeric' });

return [{
  json: {
    month: monthName,
    total_reports: totalReports,
    unique_users: uniqueUsers,
    avg_confidence: avgConfidence.toFixed(2),
    high_confidence_count: highConfidence,
    low_confidence_count: lowConfidence,
    top_companies: topCompanies,
    total_feedback: totalFeedback,
    avg_rating: avgRating,
    recommend_rate: recommendRate,
    signal_trends: signalTrends,
    generated_at: new Date().toISOString()
  }
}];

